from pathlib import Path
import json,subprocess,html,shutil
root=Path(__file__).resolve().parents[1];src=root/'build/form';dst=root/'build/form-gallery';dst.mkdir(exist_ok=True)
names=['SCORE','TIME RULE','COUNTER','FIVE PART','TUNED MEM','SWITCH','BASS ECHO','DETUNE','RATIOS','NESTED FM','BIT MORPH','CRUSH CHD','FILTER CHD','SWEEPS','BIT GROOVE','MASK SONG','NONLIN CHD','GENERATIVE','SHAPED ARP','BUILD UP','BIT PAIRS','NESTED EQ']
def encode(name):
 subprocess.run(['ffmpeg','-v','error','-y','-i',str(src/(name+'.wav')),'-c:a','libvorbis','-q:a','4',str(dst/(name+'.ogg'))],check=True)
def audio(name,label):
 encode(name);return f'<article><h3>{html.escape(label)}</h3><audio controls preload="none" src="{name}.ogg"></audio></article>'
cards=''.join(audio(f'state-{i+1:02}',f'{i+1:02} · {name}') for i,name in enumerate(names))
morph=''
for pair,label in [('byte-float','15 BIT GROOVE → 10 NESTED FM'),('byte-func','15 BIT GROOVE → 18 GENERATIVE')]:
 morph+=f'<h3>{label}</h3><div class="grid">'+''.join(audio(f'morph-{pair}-{i}',f'MORPH {pct}%') for i,pct in enumerate([0,25,50,75,100]))+'</div>'
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FORM · 22 estados — JIANT /B1T3</title><style>body{background:#111018;color:#eee9e4;font:17px/1.5 system-ui,sans-serif;margin:0}main{max-width:1100px;margin:auto;padding:28px 20px}h1{font-size:clamp(30px,5vw,55px);line-height:1.1;color:#ffb543}h2{margin-top:2em;color:#cb91ff}h3{font-size:16px}a{color:#ffb543}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:14px}article{background:#24202e;border:1px solid #493752;border-radius:12px;padding:16px}audio{width:100%}p{max-width:850px}.tag{color:#cb91ff;font-weight:700}li{margin:7px 0}</style><main><div class="tag">BYTE v0.12 · MOTOR FORM</div><h1>22 estados.<br>El espacio entre ellos.</h1><p>Adaptaciones nativas de tus 22 referencias: composición por funciones, ondas continuas, lógica de bits y cruces entre ellas. Estas muestras salen del motor en tiempo real. Conservan la misma ganancia de render, sin normalizar cada estado por separado.</p><p><a href="../../emu/">Abrir emulador</a> · <a href="../../webapp/installer/">Instalador</a> · <a href="https://github.com/juanjiant-bit/JIANT-BYTE/blob/codex/byte-identity-generator/docs/form-engine.md">Controles y relación con las referencias</a> · <a href="../../references/bytebeat-floatbeat-funcbeat.txt">Las 22 fórmulas originales</a></p><h2>Probar FORM</h2><ol><li>Mantené EDIT y girá PRESETS hasta FORM. Soltá EDIT.</li><li>Girando PRESETS recorrés los 22 estados. Pulsá PLAY para escuchar su composición.</li><li>Pulsá EDIT: en STATES elegí STATE A, STATE B y MORPH. COLOR cambia el carácter de las ecuaciones.</li><li>SELECT recorre RULES, CLOCK, NOTES y LAYERS. Hay 20 controles, además de los efectos y la matriz existentes.</li></ol><p>RUN SONG usa PLAY/STOP. RUN NOTE funciona al sostener una tecla. Los estados sin batería propia pueden combinarse con uno rítmico mediante MORPH o con una pista DRUM-X.</p><h2>Los 22 estados</h2><div class="grid">'''+cards+'''</div><h2>Entre estados</h2><p>Cada posición cambia los relojes y motivos, los pesos de eventos y secciones y la síntesis. Las alturas se ajustan a la escala elegida. Los efectos de bus siguen siendo controles de la pista.</p>'''+morph+'''<h2>Qué representa esta versión</h2><p>Son adaptaciones para los límites de BYTE, no reproducciones exactas ni un intérprete de JavaScript. La síntesis interna es mono y utiliza los buses estéreo existentes para eco y espacio. El archivo de referencias conserva las fuentes y sus créditos. GEN todavía no genera programas FORM nuevos desde ese corpus.</p></main></html>'''
(dst/'index.html').write_text(page)
shutil.copyfile(src/'metrics.json',dst/'metrics.json')
print(dst, sum(p.stat().st_size for p in dst.iterdir()),'bytes')
